type Admissao = { id:number; agenda_id:number|null; agenda_titulo:string; agenda_data:string; colaborador:string; cpf:string; mes_referencia:string; admissao:string; turno:string; registro_cargo:string; carteira:string; status_primeiro_dia:string; status_segundo_dia:string; observacoes?:string; vezes_treinado?:number; agenda_titulo_dia2?:string; agenda_data_dia2?:string; agenda_dia2_id?:number|null };
