type Treinado = { id:number; agenda_id:number; agenda_titulo:string; agenda_data:string; colaborador:string; produto_carteira:string; data_treinamento:string; tipo_treinamento:string; responsavel:string; mes_referencia:string; origem?:"admissao"|"treinamento"; cpf?:string; vezes_treinado?:number };
