function TrainingCollaboratorInput({admissions,defaultValue=""}:{admissions:Admissao[];defaultValue?:string}){const [query,setQuery]=useState(defaultValue);const [open,setOpen]=useState(false);const term=query.trim().toLocaleLowerCase("pt-BR");const filtered=admissions.filter(item=>`${item.colaborador} ${item.cpf} ${item.registro_cargo||""}`.toLocaleLowerCase("pt-BR").includes(term)).slice(0,50);return <Field label="Colaborador"><div className="relative"><input required name="colaborador" autoComplete="new-password" data-lpignore="true" value={query} className={`${inputClass} w-full`} placeholder={admissions.length?"Selecione ou digite um novo colaborador":"Digite um novo colaborador"} onFocus={()=>setOpen(true)} onBlur={()=>setTimeout(()=>setOpen(false),150)} onChange={e=>{setQuery(e.target.value);setOpen(true)}}/>{open&&admissions.length>0&&<div className="absolute z-30 mt-1 max-h-60 w-full overflow-y-auto rounded-xl border border-border bg-card p-1 shadow-2xl">{filtered.map(item=><button type="button" key={item.id} onMouseDown={e=>e.preventDefault()} onClick={()=>{setQuery(item.colaborador);setOpen(false)}} className="block w-full appearance-none rounded-lg border border-transparent bg-secondary/40 px-3 py-2 text-left text-xs text-foreground transition hover:border-primary/30 hover:bg-primary/15"><strong>{item.colaborador}</strong><span className="ml-2 text-muted-foreground">{item.cpf}{item.registro_cargo?` · ${item.registro_cargo}`:""}</span></button>)}{!filtered.length&&<p className="px-3 py-4 text-center text-xs text-muted-foreground">Nenhum admitido encontrado. Continue digitando para incluir um novo.</p>}</div>}</div><span className="text-[10px] text-muted-foreground">{admissions.length?`${admissions.length} colaborador(es) desta reunião. Você também pode digitar um nome novo.`:"Nenhum admitido vinculado. Digite o nome para incluir um novo."}</span></Field>}

