function ResponsavelQualidadeSelect({defaultValue="",value,onChange,required=true}:{defaultValue?:string;value?:string;onChange?:(value:string)=>void;required?:boolean}){const [options,setOptions]=useState<ResponsavelOption[]>([]);const [internalValue,setInternalValue]=useState(defaultValue);const selectedValue=value??internalValue;const selected=options.find(item=>item.nome.toLocaleUpperCase("pt-BR")===selectedValue.toLocaleUpperCase("pt-BR"));const [query,setQuery]=useState(defaultValue);const [open,setOpen]=useState(false);useEffect(()=>{responsaveisPromise??=listarResponsaveisQualidade();void responsaveisPromise.then(result=>setOptions(result.itens||[])).catch(()=>setOptions([]))},[]);useEffect(()=>{if(selected)setQuery(selected.nome)},[selectedValue,options]);const term=query.trim().toLocaleLowerCase("pt-BR");const filtered=options.filter(item=>`${item.nome} ${item.login}`.toLocaleLowerCase("pt-BR").includes(term));function choose(item:ResponsavelOption){if(value===undefined)setInternalValue(item.nome);onChange?.(item.nome);setQuery(item.nome);setOpen(false)}return <Field label="Responsável *"><div className="relative"><select required={required} name={required?"responsavel":"responsavel_busca"} value={selectedValue} onChange={()=>{}} className="absolute bottom-0 left-0 size-px opacity-0" tabIndex={-1}><option value="">Selecione</option>{options.map(item=><option key={item.id_usuario} value={item.nome}>{item.nome}</option>)}</select><input className={`${inputClass} w-full`} value={query} autoComplete="off" placeholder="Digite para buscar alguém da Qualidade" onFocus={()=>setOpen(true)} onBlur={()=>setTimeout(()=>setOpen(false),150)} onChange={e=>{setQuery(e.target.value);if(value===undefined)setInternalValue("");onChange?.("");setOpen(true)}}/>{open&&<div className="absolute z-30 mt-1 max-h-60 w-full overflow-y-auto rounded-xl border border-border bg-card p-1 shadow-2xl">{filtered.map(item=><button type="button" key={item.id_usuario} onMouseDown={e=>e.preventDefault()} onClick={()=>choose(item)} className="block w-full appearance-none rounded-lg border border-transparent bg-secondary/40 px-3 py-2 text-left text-xs text-foreground transition hover:border-primary/30 hover:bg-primary/15"><strong>{item.nome}</strong></button>)}{!filtered.length&&<p className="px-3 py-4 text-center text-xs text-muted-foreground">Nenhum usuário ativo do grupo Qualidade encontrado.</p>}</div>}</div><span className="text-[10px] text-muted-foreground">Somente usuários ativos com permissão QUALIDADE.</span></Field>}

function EntryModal({type,onClose,onSaved,agendas,initial,initialTraining}:{type:"admissao"|"treinamento";onClose:()=>void;onSaved:()=>void;agendas:AgendaOption[];initial?:Admissao;initialTraining?:Treinado}){
 const [saving,setSaving]=useState(false); const [error,setError]=useState("");
 const [creatingAgenda,setCreatingAgenda]=useState(false); const [availableAgendas,setAvailableAgendas]=useState(agendas);
 const [selectedAgendaId,setSelectedAgendaId]=useState(String(initial?.agenda_id||initialTraining?.agenda_id||"")); const [agendaAdmissions,setAgendaAdmissions]=useState<Admissao[]>([]);
 const [dia2Options,setDia2Options]=useState<AgendaDia2Option[]>([]); const [agendaDia2Id,setAgendaDia2Id]=useState(String(initial?.agenda_dia2_id||"")); const [dia2Touched,setDia2Touched]=useState(false); const [mostrarDia2,setMostrarDia2]=useState<boolean>(!!(initial&&((initial.status_segundo_dia&&initial.status_segundo_dia!=="PREVISTO")||initial.agenda_dia2_id)));
 const selectedAgendaOption=availableAgendas.find(a=>String(a.id)===selectedAgendaId);
 useEffect(()=>setAvailableAgendas(agendas),[agendas]);
 useEffect(()=>{if(type!=="admissao")return;void listarOpcoesAgendaDia2Treinamentos().then(result=>setDia2Options(result.itens||[])).catch(()=>setDia2Options([]))},[type]);
 useEffect(()=>{if(type!=="admissao"||dia2Touched||agendaDia2Id)return;const ciclo=selectedAgendaOption?.codigo_ciclo;if(!ciclo)return;const match=dia2Options.find(item=>item.codigo_ciclo===ciclo);if(match)setAgendaDia2Id(String(match.id))},[type,selectedAgendaId,dia2Options]);
 useEffect(()=>{if(type!=="treinamento"||!selectedAgendaId){setAgendaAdmissions([]);return}const params=new URLSearchParams({agenda_id:selectedAgendaId});void listarAdmissoesTreinamento(params).then(result=>setAgendaAdmissions(result.itens||[])).catch(()=>setAgendaAdmissions([]))},[type,selectedAgendaId]);
 async function refreshAgendas(){const [result,dia2]=await Promise.all([listarOpcoesAgendaTreinamentos(),listarOpcoesAgendaDia2Treinamentos()]);setAvailableAgendas(result.itens||[]);setDia2Options(dia2.itens||[]);setCreatingAgenda(false)}
 const semAgenda=type==="admissao"&&!selectedAgendaId; const semDia2=type==="admissao"&&!agendaDia2Id;
 const ehReal=(value:unknown)=>["PRESENTE","FALTOU","DESISTIU"].includes(String(value));
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);const data=Object.fromEntries(fd.entries());if(type==="admissao"){if(!selectedAgendaId){setError("Vincule uma agenda para registrar a admissão.");return}const marcaDia2=ehReal(data.status_segundo_dia);if(marcaDia2&&!agendaDia2Id){setError("Selecione a reunião do Dia 2 para registrar o 2º dia.");return}}setSaving(true);setError("");try{if(type==="admissao"){if(initial)await atualizarAdmissao(initial.id,data);else await criarAdmissao(data)}else{if(initialTraining)await atualizarTreinamento(initialTraining.id,data);else await criarTreinamento(data)}onSaved()}catch(err){setError(getApiError(err,"Não foi possível salvar. Confira os campos e tente novamente."))}finally{setSaving(false)}}
 return <><div className="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4"><form onSubmit={submit} className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-3xl border border-border bg-card p-6 text-foreground shadow-2xl"><div className="mb-6 flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-primary">{initial||initialTraining?"Editar cadastro":"Novo registro"}</p><h2 className="text-2xl font-bold">{type==="admissao"?(initial?"Ajustar todas as informações":"Registrar admissão"):(initialTraining?"Ajustar treinamento":"Registrar treinamento")}</h2></div><button type="button" onClick={onClose} className="grid size-9 appearance-none place-items-center rounded-lg border border-border bg-secondary/50 text-xl text-muted-foreground">×</button></div>{error&&<p className="mb-4 rounded-xl bg-red-500/10 p-3 text-sm text-red-300">{error}</p>}<div className="grid gap-4 md:grid-cols-2">
 <div className="md:col-span-2"><AgendaSelect agendas={availableAgendas} value={selectedAgendaId} onChange={setSelectedAgendaId} onCreate={()=>setCreatingAgenda(true)}/>{type==="admissao"&&<p className="mt-1 text-[10px] text-muted-foreground">Vincule uma agenda para registrar a admissão.</p>}</div>
 {type==="admissao"?<><Field label="Colaborador *"><input required name="colaborador" defaultValue={initial?.colaborador} className={inputClass}/></Field><Field label="CPF *"><input required name="cpf" defaultValue={initial?.cpf} className={inputClass} maxLength={14}/></Field><Field label="Data de admissão"><input name="admissao" type="date" defaultValue={initial?.admissao||""} className={inputClass}/></Field><Field label="Turno"><select name="turno" defaultValue={initial?.turno||""} className={inputClass}><option value="">Não informado</option>{["MANHÃ","TARDE","INTEGRAL"].map(x=><option key={x}>{x}</option>)}</select></Field><CargoSelect defaultValue={initial?.registro_cargo||""}/><CarteiraSelect defaultValue={initial?.carteira||""}/><Field label="1º dia"><select name="status_primeiro_dia" defaultValue={initial?.status_primeiro_dia||"PREVISTO"} className={inputClass}>{["PREVISTO","PRESENTE","FALTOU","DESISTIU"].map(x=><option key={x} disabled={x!=="PREVISTO"&&semAgenda}>{x}</option>)}</select>{semAgenda&&<span className="text-[10px] text-amber-300">Vincule uma agenda para registrar presença, falta ou desistência.</span>}</Field>{mostrarDia2?<Field label="2º dia"><select name="status_segundo_dia" defaultValue={initial?.status_segundo_dia||"PREVISTO"} className={inputClass}>{["PREVISTO","PRESENTE","FALTOU","DESISTIU"].map(x=><option key={x} disabled={x!=="PREVISTO"&&semDia2}>{x}</option>)}</select>{semDia2&&<span className="text-[10px] text-amber-300">Selecione a reunião do Dia 2 para registrar o 2º dia.</span>}</Field>:<Field label="2º dia"><button type="button" onClick={()=>setMostrarDia2(true)} className={`${buttonSoft} h-10 w-full`}>+ Registrar 2º dia</button><span className="text-[10px] text-muted-foreground">Adicione o 2º dia apenas quando houver.</span></Field>}{mostrarDia2&&<div className="md:col-span-2"><AgendaDia2Select options={dia2Options} value={agendaDia2Id} onChange={value=>{setDia2Touched(true);setAgendaDia2Id(value)}} onCreate={()=>setCreatingAgenda(true)}/><div className="mt-1 flex flex-wrap items-center justify-between gap-2"><span className="text-[10px] text-muted-foreground">Vincule a reunião do Dia 2. Necessária para registrar presença/falta/desistência no 2º dia.</span><button type="button" onClick={()=>{setMostrarDia2(false);setAgendaDia2Id("");setDia2Touched(false)}} className="inline-flex h-8 appearance-none items-center justify-center rounded-lg border border-red-400/30 bg-red-500/10 px-3 text-xs font-bold text-red-300 transition hover:border-red-400/60 hover:bg-red-500/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-400/40">Remover 2º dia</button></div></div>}<label className="grid gap-1 text-xs font-semibold text-muted-foreground md:col-span-2">Observações<textarea name="observacoes" defaultValue={initial?.observacoes} className="min-h-24 rounded-xl border border-border bg-input p-3 text-sm text-foreground caret-primary placeholder:text-muted-foreground"/></label></>
 :<><TrainingCollaboratorInput admissions={agendaAdmissions} defaultValue={initialTraining?.colaborador||""}/><CarteiraSelect name="produto_carteira" label="Produto / carteira" defaultValue={initialTraining?.produto_carteira||""} required/><Field label="Data"><input required name="data_treinamento" type="date" defaultValue={initialTraining?.data_treinamento||today} className={inputClass}/></Field><Field label="Situação"><select name="tipo_treinamento" defaultValue={initialTraining?.tipo_treinamento||"INICIAL"} className={inputClass}>{["INICIAL","REMANEJAMENTO","CALIBRAGEM"].map(x=><option key={x}>{x}</option>)}</select></Field><MultiResponsavelSelect defaultValue={initialTraining?.responsavel||""}/></>}
 </div><div className="mt-6 flex justify-end gap-3"><button type="button" onClick={onClose} className={buttonSecondary}>Cancelar</button><button disabled={saving} className={`${buttonPrimary} px-5`}>{saving?"Salvando…":"Salvar registro"}</button></div></form></div>{creatingAgenda&&<AgendaModal date={initial?.admissao||initialTraining?.data_treinamento||today} onClose={()=>setCreatingAgenda(false)} onSaved={()=>void refreshAgendas()}/>}</>
}

type AdmissionDraft = Omit<Admissao,"id"|"mes_referencia"|"agenda_id"|"agenda_titulo"|"agenda_data"> & { agenda_id:string; erros?:string[] };
const emptyAdmission=():AdmissionDraft=>({agenda_id:"",colaborador:"",cpf:"",admissao:"",turno:"",registro_cargo:"",carteira:"",status_primeiro_dia:"PREVISTO",status_segundo_dia:"PREVISTO",observacoes:"",erros:[]});

function AdmissionDraftCard({row,index,onChange,onRemove}:{row:AdmissionDraft;index:number;onChange:(index:number,key:keyof AdmissionDraft,value:string)=>void;onRemove:()=>void}){return <article className={`rounded-xl border p-3 ${row.erros?.length?"border-red-400/40 bg-red-500/5":"border-border bg-secondary/20"}`}><div className="mb-3 flex items-center justify-between"><span className="text-xs font-bold text-primary">Registro {index+1}</span><button onClick={onRemove} className={buttonDanger}>Remover</button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-6"><Field label="Colaborador"><input value={row.colaborador} onChange={e=>onChange(index,"colaborador",e.target.value)} className={`${inputClass} w-full`}/></Field><Field label="CPF"><input value={row.cpf} onChange={e=>onChange(index,"cpf",e.target.value)} className={`${inputClass} w-full`}/></Field><Field label="Admissão"><input type="date" value={row.admissao} onChange={e=>onChange(index,"admissao",e.target.value)} className={`${inputClass} w-full`}/></Field><Field label="Turno"><select value={row.turno} onChange={e=>onChange(index,"turno",e.target.value)} className={`${inputClass} w-full`}>{["MANHÃ","TARDE","INTEGRAL"].map(x=><option key={x}>{x}</option>)}</select></Field><CargoSelect value={row.registro_cargo} onChange={value=>onChange(index,"registro_cargo",value)}/><CarteiraSelect value={row.carteira} onChange={value=>onChange(index,"carteira",value)}/><Field label="1º dia"><select value={row.status_primeiro_dia} onChange={e=>onChange(index,"status_primeiro_dia",e.target.value)} className={`${inputClass} w-full`}>{["PREVISTO","PRESENTE","FALTOU","DESISTIU"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="2º dia"><select value={row.status_segundo_dia} onChange={e=>onChange(index,"status_segundo_dia",e.target.value)} className={`${inputClass} w-full`}>{["PREVISTO","PRESENTE","FALTOU","DESISTIU"].map(x=><option key={x}>{x}</option>)}</select></Field><div className="sm:col-span-2 lg:col-span-2 xl:col-span-4"><Field label="Observações"><input value={row.observacoes||""} onChange={e=>onChange(index,"observacoes",e.target.value)} className={`${inputClass} w-full`}/></Field></div></div>{row.erros?.length?<p className="mt-2 text-[10px] text-red-300">{row.erros.join(" · ")}</p>:null}</article>}

function BatchAdmissionsModal({onClose,onSaved,agendas}:{onClose:()=>void;onSaved:()=>void;agendas:AgendaOption[]}){
 const [mode,setMode]=useState<"manual"|"excel">("manual");const [rows,setRows]=useState<AdmissionDraft[]>([emptyAdmission()]);const [loading,setLoading]=useState(false);const [error,setError]=useState("");const [fileName,setFileName]=useState("");
 function change(index:number,key:keyof AdmissionDraft,value:string){setRows(current=>current.map((row,i)=>i===index?{...row,[key]:value,erros:[]}:row))}
 async function analyze(file?:File){if(!file)return;setLoading(true);setError("");try{const result=await analisarPlanilhaAdmissoes(file);setFileName(`${result.arquivo} · ${result.aba}`);setRows(result.itens.map((item:{dados:AdmissionDraft;erros:string[]})=>({...item.dados,erros:item.erros})));}catch(e){setError("Não foi possível analisar a planilha. Confira os cabeçalhos e o formato do arquivo.")}finally{setLoading(false)}}
 async function confirm(){if(rows.some(row=>!row.agenda_id)){setError("Selecione a agenda acima para vincular todas as linhas antes de confirmar.");return}setLoading(true);setError("");try{await criarAdmissoesLote(rows.map(({erros,...row})=>row));onSaved()}catch(err){setError(getApiError(err,"Existem campos inválidos ou incompletos. Ajuste as linhas destacadas antes de confirmar."))}finally{setLoading(false)}}
 return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-3"><section className="flex max-h-[94vh] w-full max-w-[1450px] flex-col overflow-hidden rounded-3xl border border-border bg-card shadow-2xl"><header className="flex flex-wrap items-start justify-between gap-3 border-b border-border p-5"><div><p className="text-xs font-bold uppercase tracking-widest text-primary">Inclusão em lote</p><h2 className="text-2xl font-bold">Pré-visualizar admissões</h2><p className="text-sm text-muted-foreground">Revise e altere qualquer célula. Os dados só serão gravados após a confirmação.</p></div><button onClick={onClose} className="grid size-9 appearance-none place-items-center rounded-lg border border-border bg-secondary/50 text-xl text-muted-foreground hover:border-primary/50 hover:text-foreground">×</button></header>
  <div className="flex flex-wrap items-center gap-3 border-b border-border p-4"><div className="flex rounded-xl border border-border bg-secondary/30 p-1"><button onClick={()=>{setMode("manual");setRows([emptyAdmission()]);setFileName("")}} className={`h-9 appearance-none rounded-lg border px-4 text-sm font-bold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40 ${mode==="manual"?"border-primary bg-primary text-primary-foreground":"border-transparent bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground"}`}>Digitar manualmente</button><button onClick={()=>setMode("excel")} className={`h-9 appearance-none rounded-lg border px-4 text-sm font-bold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40 ${mode==="excel"?"border-primary bg-primary text-primary-foreground":"border-transparent bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground"}`}>Importar Excel</button></div>{mode==="manual"?<button onClick={()=>setRows(r=>[...r,emptyAdmission()])} className={buttonSoft}>+ Adicionar linha</button>:<><a href="/modelo_admissoes_treinamentos.xlsx" download className={buttonSecondary}>Baixar modelo</a><label className={`${buttonSoft} cursor-pointer`}>Selecionar .xlsx ou .xlsm<input type="file" accept=".xlsx,.xlsm" className="hidden" onChange={e=>void analyze(e.target.files?.[0])}/></label></>} {fileName&&<span className="text-xs text-muted-foreground">{fileName}</span>}<span className="ml-auto text-sm font-semibold text-muted-foreground">{rows.length} registro(s)</span></div>
  <div className="border-b border-border p-4"><AgendaSelect agendas={agendas} value={rows.length&&rows.every(row=>row.agenda_id===rows[0].agenda_id)?rows[0].agenda_id:""} onChange={agenda_id=>{const agenda=agendas.find(item=>String(item.id)===agenda_id);setRows(current=>current.map(row=>({...row,agenda_id,admissao:row.admissao||agenda?.data_treinamento||"",carteira:row.carteira||agenda?.produto_carteira||"",erros:[]})))}}/><p className="mt-1 text-xs text-muted-foreground">No Excel, somente COLABORADOR/NOME e CPF são obrigatórios. Escolha aqui a agenda para preencher todas as linhas; data e carteira vazias serão sugeridas pela agenda e poderão ser revisadas individualmente.</p></div>
  {error&&<p className="m-4 rounded-xl border border-red-400/30 bg-red-500/10 p-3 text-sm text-red-300">{error}</p>}
  <div className="min-h-0 flex-1 space-y-3 overflow-y-auto bg-card p-4">{rows.map((row,index)=><AdmissionDraftCard key={index} row={row} index={index} onChange={change} onRemove={()=>setRows(current=>current.filter((_,i)=>i!==index))}/>)}</div>
  <footer className="flex items-center justify-between gap-3 border-t border-border bg-card p-4"><p className="text-xs text-muted-foreground">Limite de 5.000 registros por confirmação.</p><div className="flex gap-3"><button onClick={onClose} className={buttonSecondary}>Cancelar</button><button disabled={loading||!rows.length} onClick={()=>void confirm()} className={`${buttonPrimary} px-5`}>{loading?"Processando…":`Confirmar ${rows.length} registro(s)`}</button></div></footer>
 </section></div>
}

type TrainingDraft = Omit<Treinado,"id"|"mes_referencia"|"agenda_id"|"agenda_titulo"|"agenda_data"> & { agenda_id:string; erros?:string[] };
const emptyTraining=():TrainingDraft=>({agenda_id:"",colaborador:"",produto_carteira:"",data_treinamento:today,tipo_treinamento:"INICIAL",responsavel:"",erros:[]});

function TrainingDraftCard({row,index,onChange,onRemove}:{row:TrainingDraft;index:number;onChange:(index:number,key:keyof TrainingDraft,value:string)=>void;onRemove:()=>void}){return <article className={`rounded-xl border p-3 ${row.erros?.length?"border-red-400/40 bg-red-500/5":"border-border bg-secondary/20"}`}><div className="mb-3 flex items-center justify-between"><span className="text-xs font-bold text-primary">Registro {index+1}</span><button onClick={onRemove} className={buttonDanger}>Remover</button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Field label="Colaborador"><input value={row.colaborador} onChange={e=>onChange(index,"colaborador",e.target.value)} className={`${inputClass} w-full`}/></Field><CarteiraSelect name="produto_carteira" label="Produto / carteira" value={row.produto_carteira} onChange={value=>onChange(index,"produto_carteira",value)} required/><Field label="Data"><input type="date" value={row.data_treinamento} onChange={e=>onChange(index,"data_treinamento",e.target.value)} className={`${inputClass} w-full`}/></Field><Field label="Situação"><select value={row.tipo_treinamento} onChange={e=>onChange(index,"tipo_treinamento",e.target.value)} className={`${inputClass} w-full`}>{["INICIAL","REMANEJAMENTO","CALIBRAGEM"].map(x=><option key={x}>{x}</option>)}</select></Field><ResponsavelQualidadeSelect value={row.responsavel} onChange={value=>onChange(index,"responsavel",value)}/></div>{row.erros?.length?<p className="mt-2 text-[10px] text-red-300">{row.erros.join(" · ")}</p>:null}</article>}

function BatchTrainingsModal({onClose,onSaved,agendas}:{onClose:()=>void;onSaved:()=>void;agendas:AgendaOption[]}){
 const [mode,setMode]=useState<"manual"|"excel">("manual");const [rows,setRows]=useState<TrainingDraft[]>([emptyTraining()]);const [loading,setLoading]=useState(false);const [error,setError]=useState("");const [fileName,setFileName]=useState("");
 function change(index:number,key:keyof TrainingDraft,value:string){setRows(current=>current.map((row,i)=>i===index?{...row,[key]:value,erros:[]}:row))}
 async function analyze(file?:File){if(!file)return;setLoading(true);setError("");try{const result=await analisarPlanilhaTreinamentos(file);setFileName(`${result.arquivo} · ${result.aba}`);setRows(result.itens.map((item:{dados:TrainingDraft;erros:string[]})=>({...item.dados,erros:item.erros})));}catch{setError("Não foi possível analisar a planilha. Confira os cabeçalhos e o formato do arquivo.")}finally{setLoading(false)}}
 async function save(){setLoading(true);setError("");try{await criarTreinamentosLote(rows.map(({erros,...row})=>row));onSaved()}catch{setError("Existem campos inválidos ou incompletos. Ajuste as linhas destacadas antes de confirmar.")}finally{setLoading(false)}}
 return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-3"><section className="flex max-h-[94vh] w-full max-w-[1200px] flex-col overflow-hidden rounded-3xl border border-border bg-card shadow-2xl"><header className="flex items-start justify-between border-b border-border p-5"><div><p className="text-xs font-bold uppercase tracking-widest text-primary">Inclusão em lote</p><h2 className="text-2xl font-bold">Pré-visualizar treinamentos</h2><p className="text-sm text-muted-foreground">Revise todas as informações antes de gravar.</p></div><button onClick={onClose} className="grid size-9 appearance-none place-items-center rounded-lg border border-border bg-secondary/50 text-xl text-muted-foreground">×</button></header>
 <div className="flex flex-wrap items-center gap-3 border-b border-border p-4"><div className="flex rounded-xl border border-border bg-secondary/30 p-1"><button onClick={()=>{setMode("manual");setRows([emptyTraining()]);setFileName("")}} className={`h-9 appearance-none rounded-lg border px-4 text-sm font-bold ${mode==="manual"?"border-primary bg-primary text-primary-foreground":"border-transparent bg-transparent text-muted-foreground"}`}>Digitar manualmente</button><button onClick={()=>setMode("excel")} className={`h-9 appearance-none rounded-lg border px-4 text-sm font-bold ${mode==="excel"?"border-primary bg-primary text-primary-foreground":"border-transparent bg-transparent text-muted-foreground"}`}>Importar Excel</button></div>{mode==="manual"?<button onClick={()=>setRows(r=>[...r,emptyTraining()])} className={buttonSoft}>+ Adicionar linha</button>:<><a href="/modelo_importacao_treinamentos.xlsx" download className={buttonSecondary}>Baixar modelo</a><label className={`${buttonSoft} cursor-pointer`}>Selecionar .xlsx ou .xlsm<input type="file" accept=".xlsx,.xlsm" className="hidden" onChange={e=>void analyze(e.target.files?.[0])}/></label></>}{fileName&&<span className="text-xs text-muted-foreground">{fileName}</span>}<span className="ml-auto text-sm text-muted-foreground">{rows.length} registro(s)</span></div>
 <div className="border-b border-border p-4"><AgendaSelect agendas={agendas} value={rows.length&&rows.every(row=>row.agenda_id===rows[0].agenda_id)?rows[0].agenda_id:""} onChange={agenda_id=>setRows(current=>current.map(row=>({...row,agenda_id,erros:[]})))}/><p className="mt-1 text-xs text-muted-foreground">A seleção é aplicada a todas as linhas. No Excel, use a coluna ID AGENDA para vincular cada registro individualmente.</p></div>
 {error&&<p className="m-4 rounded-xl bg-red-500/10 p-3 text-sm text-red-300">{error}</p>}<div className="min-h-0 flex-1 space-y-3 overflow-y-auto p-4">{rows.map((row,index)=><TrainingDraftCard key={index} row={row} index={index} onChange={change} onRemove={()=>setRows(current=>current.filter((_,i)=>i!==index))}/>)}</div>
 <footer className="flex items-center justify-between border-t border-border p-4"><p className="text-xs text-muted-foreground">Limite de 5.000 registros.</p><div className="flex gap-3"><button onClick={onClose} className={buttonSecondary}>Cancelar</button><button disabled={loading||!rows.length} onClick={()=>void save()} className={`${buttonPrimary} px-5`}>{loading?"Processando…":`Confirmar ${rows.length} registro(s)`}</button></div></footer></section></div>
}

function TrainingAgendaV3(){
 const [month,setMonth]=useState(startOfMonth(new Date()));const [selected,setSelected]=useState(new Date());const [items,setItems]=useState<AgendaItem[]>([]);const [loading,setLoading]=useState(true);const [formDate,setFormDate]=useState<string|null>(null);const [editing,setEditing]=useState<AgendaItem|null>(null);const [operador,setOperador]=useState<string|null>(null);
 const gridStart=startOfWeek(startOfMonth(month),{weekStartsOn:0});const gridEnd=endOfWeek(endOfMonth(month),{weekStartsOn:0});
 const days=useMemo(()=>{const list:Date[]=[];for(let cursor=gridStart;cursor<=gridEnd;cursor=new Date(cursor.getFullYear(),cursor.getMonth(),cursor.getDate()+1))list.push(cursor);return list},[gridStart.getTime(),gridEnd.getTime()]);
 const load=useCallback(async()=>{setLoading(true);try{const params=new URLSearchParams({inicio:format(gridStart,"yyyy-MM-dd"),fim:format(gridEnd,"yyyy-MM-dd")});setItems((await listarAgendaTreinamentos(params)).itens)}finally{setLoading(false)}},[gridStart.getTime(),gridEnd.getTime()]);
 useEffect(()=>{void load()},[load]);useEffect(()=>{const refresh=()=>void load();window.addEventListener("atlas:training-changed",refresh);return()=>window.removeEventListener("atlas:training-changed",refresh)},[load]);const selectedKey=format(selected,"yyyy-MM-dd");const selectedItems=items.filter(item=>item.data_treinamento===selectedKey);
 function selectDay(day:Date){setSelected(day);if(!isSameMonth(day,month))setMonth(startOfMonth(day))}
 async function remove(item:AgendaItem){const vinculos=item.quantidade_admissoes+item.quantidade_treinamentos;const detalhe=vinculos?`\n\nTambém serão excluídos ${item.quantidade_admissoes} registro(s) de admissão e ${item.quantidade_treinamentos} registro(s) de treinamento vinculados.`:"";if(!confirm(`Excluir o agendamento \"${item.titulo}\"?${detalhe}\n\nEsta ação não pode ser desfeita.`))return;try{await excluirAgendaTreinamento(item.id);await load()}catch{alert("Não foi possível excluir o agendamento. Atualize a página e tente novamente.")}}
 function openParticipant(_item:AgendaItem,name:string){setOperador(name)}
 return <div className="min-h-full min-w-0 overflow-x-hidden bg-background text-foreground"><div className="mx-auto w-full max-w-[1280px] px-4 py-5 sm:px-6"><header className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">Qualidade</p><h1 className="mt-1 text-3xl font-bold">Treinamentos</h1><p className="mt-1 text-sm text-muted-foreground">Planejamento mensal das capacitações, sem notificações por e-mail.</p></div><button onClick={()=>setFormDate(selectedKey)} className={`${buttonPrimary} h-11 px-5`}>+ Agendar treinamento</button></header><main className="mt-6 grid min-w-0 gap-6 xl:grid-cols-[minmax(360px,430px)_minmax(0,1fr)] xl:items-start"><section className="rounded-2xl border border-border bg-card p-4 shadow-xl"><p className="text-xs font-bold text-foreground">Calendário</p><div className="mt-4 grid grid-cols-[32px_1fr_32px] items-center gap-2"><button onClick={()=>setMonth(addMonths(month,-1))} className="flex size-8 appearance-none items-center justify-center rounded-full border-0 bg-transparent text-muted-foreground transition hover:bg-secondary hover:text-foreground">‹</button><h2 className="text-center text-base font-bold capitalize">{format(month,"MMMM 'de' yyyy",{locale:ptBR})}</h2><button onClick={()=>setMonth(addMonths(month,1))} className="flex size-8 appearance-none items-center justify-center rounded-full border-0 bg-transparent text-muted-foreground transition hover:bg-secondary hover:text-foreground">›</button></div><button onClick={()=>{const now=new Date();setMonth(startOfMonth(now));setSelected(now)}} className="mx-auto mt-2 block appearance-none rounded-full border border-primary/40 bg-transparent px-3 py-1 text-xs font-semibold text-primary transition hover:bg-primary/10">Hoje</button><p className="mt-2 text-center text-xs capitalize text-muted-foreground">{format(selected,"EEEE, dd 'de' MMMM 'de' yyyy",{locale:ptBR})}</p><div className="mt-4 grid grid-cols-7 text-center text-xs uppercase tracking-wider text-muted-foreground">{["D","S","T","Q","Q","S","S"].map((day,index)=><div key={`${day}-${index}`} className="py-2 font-medium">{day}</div>)}</div><div className="grid grid-cols-7 gap-y-1">{days.map(day=>{const key=format(day,"yyyy-MM-dd");const dayItems=items.filter(item=>item.data_treinamento===key);const active=isSameDay(day,selected);return <button key={key} onClick={()=>selectDay(day)} className={`group flex h-10 w-full appearance-none flex-col items-center justify-start gap-0.5 border-0 bg-transparent p-0 text-sm font-semibold transition ${isSameMonth(day,month)?"text-foreground":"text-muted-foreground/35"}`}><span className={`flex size-7 items-center justify-center rounded-full transition ${active?"bg-primary text-primary-foreground shadow-lg shadow-primary/25":isSameDay(day,new Date())?"text-primary":"group-hover:bg-secondary"}`}>{format(day,"d")}</span><span className="flex h-1.5 items-center justify-center gap-0.5">{dayItems.slice(0,3).map(item=><span key={item.id} className={`size-1.5 rounded-full ${item.status_agenda==="CANCELADO"?"bg-red-400":item.status_agenda==="REALIZADO"?"bg-emerald-400":"bg-primary"}`}/>)}</span></button>})}</div></section><section className="min-w-0 rounded-2xl border border-border bg-card p-4 shadow-xl sm:p-5"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-primary">Treinamentos do dia</p><h2 className="text-xl font-bold">{formatDate(selectedKey)}</h2></div><div className="flex items-center gap-2"><span className="rounded-full bg-primary/20 px-3 py-1 text-xs font-bold text-primary">{selectedItems.length}</span><button onClick={()=>setFormDate(selectedKey)} className={`${buttonSoft} h-9 px-3 text-xs`}>+ Novo treinamento</button></div></div>{loading?<p className="text-sm text-muted-foreground">Carregando…</p>:selectedItems.length?<div className="space-y-3">{selectedItems.map(item=><article key={item.id} className="group rounded-xl border border-border bg-secondary/35 p-4 transition hover:border-primary/60 hover:bg-muted/60"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-primary/15 px-3 py-1 text-xs font-bold text-primary">{item.horario_inicio} - {item.horario_fim}</span><h3 className="break-words font-bold">{item.titulo}</h3></div><div className="mt-2"><AgendaStatusBadge value={item.status_agenda}/></div><p className="mt-2 text-xs text-muted-foreground">Criado por {item.responsavel}</p></div><div className="ml-auto flex shrink-0 gap-2 opacity-100 transition lg:pointer-events-none lg:opacity-0 lg:group-hover:pointer-events-auto lg:group-hover:opacity-100 lg:group-focus-within:pointer-events-auto lg:group-focus-within:opacity-100"><button onClick={()=>setEditing(item)} className={`${buttonSecondary} h-8 w-20 px-3 text-xs`}>Editar</button><button onClick={()=>void remove(item)} className={buttonDanger}>Excluir</button></div></div><div className="mt-3 grid grid-cols-1 gap-3 border-t border-border pt-3 text-sm sm:grid-cols-2"><Info label="Carteira" value={item.produto_carteira}/><Info label="Tipo" value={item.tipo_treinamento}/></div><ParticipantsByWallet groups={item.participantes_por_carteira} onParticipantClick={name=>openParticipant(item,name)}/>{item.observacoes&&<p className="mt-3 border-t border-border pt-2 text-xs text-muted-foreground">{item.observacoes}</p>}</article>)}</div>:<div className="rounded-xl border border-border bg-secondary/40 p-5 text-sm text-muted-foreground">Nenhum treinamento nesta data.</div>}</section></main></div>{(formDate||editing)&&<AgendaModal date={editing?.data_treinamento||formDate||selectedKey} item={editing||undefined} onClose={()=>{setFormDate(null);setEditing(null)}} onSaved={()=>{setFormDate(null);setEditing(null);void load()}}/>}{operador&&<OperatorHistoryModal nome={operador} onClose={()=>setOperador(null)} onChanged={()=>void load()}/>}</div>
}

function diasTreinados(item:Admissao):(1|2)[]{const dias:(1|2)[]=[];const p1=item.status_primeiro_dia==="PRESENTE";const p2=item.status_segundo_dia==="PRESENTE";if(p1||(!p1&&!p2))dias.push(1);if(p2)dias.push(2);return dias}
function AdmissionDayCard({item,dia,onEdit}:{item:Admissao;dia:1|2;onEdit:()=>void}){const titulo=dia===2?(item.agenda_titulo_dia2||item.agenda_titulo):item.agenda_titulo;const data=dia===2?(item.agenda_data_dia2||item.agenda_data):item.agenda_data;const status=dia===2?item.status_segundo_dia:item.status_primeiro_dia;const semReuniaoDia2=dia===2&&!item.agenda_titulo_dia2;return <article className="rounded-xl border border-border bg-secondary/30 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap items-center gap-2"><OriginBadge value="admissao"/><span className="rounded-full border border-border bg-background/40 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-muted-foreground">Dia {dia}</span><span className="text-xs font-semibold text-muted-foreground">{titulo} · {formatDate(data)}</span>{semReuniaoDia2&&<span className="text-[10px] font-semibold text-amber-300">Reunião do Dia 2 não cadastrada</span>}</div><button onClick={onEdit} className={`${buttonSoft} h-8 px-3 text-xs`}>Editar</button></div><div className="mt-3 grid grid-cols-2 gap-3 text-sm sm:grid-cols-4"><Info label="Data admissão" value={formatDate(item.admissao)}/><Info label="Turno" value={item.turno||"Não informado"}/><Info label="Cargo" value={item.registro_cargo||"Não informado"}/><Info label="Carteira" value={item.carteira||"Não informada"}/><StatusInfo label={`${dia}º dia`} value={status}/></div>{dia===1&&item.observacoes&&<p className="mt-3 border-t border-border pt-2 text-xs text-muted-foreground">{item.observacoes}</p>}</article>}
function OperatorHistoryModal({cpf,nome,onClose,onChanged}:{cpf?:string;nome?:string;onClose:()=>void;onChanged?:()=>void}){
 const [record,setRecord]=useState<OperadorHistorico|null>(null);const [loading,setLoading]=useState(true);
 const [agendas,setAgendas]=useState<AgendaOption[]>([]);const [editingAdmission,setEditingAdmission]=useState<Admissao|null>(null);const [editingTraining,setEditingTraining]=useState<Treinado|null>(null);
 const load=useCallback(async()=>{setLoading(true);const params=new URLSearchParams();if(cpf)params.set("cpf",cpf);if(nome)params.set("nome",nome);try{setRecord(await listarHistoricoOperador(params))}catch{setRecord(null)}finally{setLoading(false)}},[cpf,nome]);
 useEffect(()=>{void load()},[load]);
 useEffect(()=>{void listarOpcoesAgendaTreinamentos().then(result=>setAgendas(result.itens||[])).catch(()=>setAgendas([]))},[]);
 function saved(){setEditingAdmission(null);setEditingTraining(null);window.dispatchEvent(new Event("atlas:training-changed"));onChanged?.();void load()}
 const titulo=record?.nome||nome||"Operador";
 return <><div className="fixed inset-0 z-[60] grid place-items-center bg-black/75 p-3"><section className="flex max-h-[90vh] w-full max-w-3xl flex-col overflow-hidden rounded-3xl border border-border bg-card shadow-2xl"><header className="flex items-start justify-between gap-3 border-b border-border p-5"><div className="min-w-0"><p className="text-xs font-bold uppercase tracking-widest text-primary">Histórico do operador</p><div className="mt-1 flex flex-wrap items-center gap-2"><h2 className="break-words text-2xl font-bold">{titulo}</h2><TrainedCountBadge count={record?.vezes_treinado}/></div>{record?.cpf&&<p className="mt-1 text-xs text-muted-foreground">CPF {record.cpf}</p>}</div><button onClick={onClose} className={`${buttonSecondary} size-10 px-0`}>×</button></header><div className="min-h-0 flex-1 space-y-4 overflow-y-auto p-4">{loading?<p className="text-sm text-muted-foreground">Carregando histórico consolidado…</p>:<>{record&&(record.admissoes.length+record.treinamentos.length>0)?<><p className="text-xs text-muted-foreground">Todos os treinamentos vinculados a este operador em qualquer agenda.</p>{record.admissoes.flatMap(item=>diasTreinados(item).map(dia=><AdmissionDayCard key={`a-${item.id}-${dia}`} item={item} dia={dia} onEdit={()=>setEditingAdmission(item)}/>))}{record.treinamentos.map(item=><article key={`t-${item.id}`} className="rounded-xl border border-border bg-secondary/30 p-4"><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><OriginBadge value="treinamento"/><span className="text-xs font-semibold text-muted-foreground">{item.agenda_titulo} · {formatDate(item.agenda_data)}</span></div><button onClick={()=>setEditingTraining(item)} className={`${buttonSoft} h-8 px-3 text-xs`}>Editar</button></div><div className="mt-3 grid grid-cols-2 gap-3 text-sm sm:grid-cols-4"><Info label="Data" value={formatDate(item.data_treinamento)}/><Info label="Carteira" value={item.produto_carteira}/><Info label="Tipo" value={item.tipo_treinamento}/><Info label="Responsável" value={item.responsavel}/></div></article>)}</>:<p className="rounded-xl border border-border bg-secondary/30 p-4 text-sm text-muted-foreground">Nenhum treinamento encontrado para este operador.</p>}</>}</div></section></div>{editingAdmission&&<EntryModal type="admissao" agendas={agendas} initial={editingAdmission} onClose={()=>setEditingAdmission(null)} onSaved={saved}/>}{editingTraining&&<EntryModal type="treinamento" agendas={agendas} initialTraining={editingTraining} onClose={()=>setEditingTraining(null)} onSaved={saved}/>}</>
}

function TrainingAgendaV2(){
 const [month,setMonth]=useState(startOfMonth(new Date()));const [items,setItems]=useState<AgendaItem[]>([]);const [loading,setLoading]=useState(true);const [selectedDay,setSelectedDay]=useState<string|null>(null);const [formDate,setFormDate]=useState<string|null>(null);const [editing,setEditing]=useState<AgendaItem|null>(null);
 const gridStart=startOfWeek(startOfMonth(month),{weekStartsOn:0});const gridEnd=endOfWeek(endOfMonth(month),{weekStartsOn:0});
 const days=useMemo(()=>{const list:Date[]=[];for(let cursor=gridStart;cursor<=gridEnd;cursor=new Date(cursor.getFullYear(),cursor.getMonth(),cursor.getDate()+1))list.push(cursor);return list},[gridStart.getTime(),gridEnd.getTime()]);
 const load=useCallback(async()=>{setLoading(true);try{const params=new URLSearchParams({inicio:format(gridStart,"yyyy-MM-dd"),fim:format(gridEnd,"yyyy-MM-dd")});setItems((await listarAgendaTreinamentos(params)).itens)}finally{setLoading(false)}},[gridStart.getTime(),gridEnd.getTime()]);
 useEffect(()=>{void load()},[load]);
 const dayItems=selectedDay?items.filter(item=>item.data_treinamento===selectedDay):[];
 async function remove(item:AgendaItem){if(!confirm("Excluir este agendamento?"))return;await excluirAgendaTreinamento(item.id);await load()}
 return <div className="min-h-full min-w-0 overflow-x-hidden bg-background p-3 text-foreground sm:p-5 lg:h-[calc(100vh-5rem)] lg:overflow-hidden"><div className="mx-auto flex h-full w-full max-w-[1500px] min-w-0 flex-col gap-4"><header className="flex shrink-0 flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">Qualidade</p><h1 className="mt-1 text-2xl font-bold sm:text-3xl">Treinamentos</h1><p className="mt-1 text-sm text-muted-foreground">Planejamento mensal das capacitações.</p></div><button onClick={()=>setFormDate(today)} className={`${buttonPrimary} h-10 px-4`}>+ Agendar treinamento</button></header><section className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl border border-border bg-card shadow-xl"><div className="flex shrink-0 items-center justify-between border-b border-border px-3 py-2"><button onClick={()=>setMonth(addMonths(month,-1))} className={`${buttonSecondary} size-9 px-0`}>‹</button><div className="text-center"><p className="text-[10px] font-bold uppercase tracking-widest text-primary">Agenda mensal</p><h2 className="text-lg font-bold capitalize">{format(month,"MMMM 'de' yyyy",{locale:ptBR})}</h2></div><button onClick={()=>setMonth(addMonths(month,1))} className={`${buttonSecondary} size-9 px-0`}>›</button></div><div className="grid shrink-0 grid-cols-7 border-b border-border bg-secondary/30">{["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map(day=><div key={day} className="px-1 py-2 text-center text-[10px] font-bold uppercase text-muted-foreground">{day}</div>)}</div><div className="grid min-h-[420px] flex-1 grid-cols-7 lg:min-h-0">{days.map(day=>{const key=format(day,"yyyy-MM-dd");const events=items.filter(item=>item.data_treinamento===key);return <button type="button" key={key} onClick={()=>setSelectedDay(key)} className={`group min-h-16 min-w-0 appearance-none overflow-hidden border-b border-r border-border p-1.5 text-left align-top transition hover:bg-primary/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary ${isSameMonth(day,month)?"bg-card text-foreground":"bg-background/40 text-muted-foreground/40"}`}><div className="flex items-center justify-between"><span className={`grid size-6 place-items-center rounded-full text-[11px] font-bold ${key===today?"bg-primary text-primary-foreground":""}`}>{format(day,"d")}</span>{events.length>0&&<span className="rounded-full bg-primary/15 px-1.5 py-0.5 text-[9px] font-bold text-primary">{events.length}</span>}</div>{events.length>0&&<div className="mt-1 hidden min-w-0 xl:block"><p className="truncate text-[10px] font-semibold text-foreground">{events[0].horario_inicio} · {events[0].titulo}</p>{events.length>1&&<p className="text-[9px] font-bold text-primary">+ {events.length-1} reunião(ões)</p>}</div>}</button>})}</div></section>{loading&&<p className="shrink-0 text-center text-xs text-muted-foreground">Atualizando agenda…</p>}</div>{selectedDay&&<AgendaDaySummary date={selectedDay} items={dayItems} onClose={()=>setSelectedDay(null)} onNew={()=>setFormDate(selectedDay)} onEdit={setEditing} onDelete={item=>void remove(item)}/>} {(formDate||editing)&&<AgendaModal date={editing?.data_treinamento||formDate||today} item={editing||undefined} onClose={()=>{setFormDate(null);setEditing(null)}} onSaved={()=>{setFormDate(null);setEditing(null);void load()}}/>}</div>
}

function AgendaDaySummary({date,items,onClose,onNew,onEdit,onDelete}:{date:string;items:AgendaItem[];onClose:()=>void;onNew:()=>void;onEdit:(item:AgendaItem)=>void;onDelete:(item:AgendaItem)=>void}){return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-3"><section className="flex max-h-[92vh] w-full max-w-4xl flex-col overflow-hidden rounded-3xl border border-border bg-card shadow-2xl"><header className="flex shrink-0 items-start justify-between gap-3 border-b border-border p-4 sm:p-5"><div><p className="text-xs font-bold uppercase tracking-widest text-primary">Resumo do dia</p><h2 className="text-xl font-bold sm:text-2xl">{formatDate(date)}</h2><p className="text-sm text-muted-foreground">{items.length} reunião(ões) agendada(s)</p></div><div className="flex gap-2"><button onClick={onNew} className={buttonPrimary}>+ Novo treinamento</button><button onClick={onClose} className={`${buttonSecondary} size-10 px-0`}>×</button></div></header><div className="min-h-0 flex-1 space-y-3 overflow-y-auto p-3 sm:p-4">{items.length?items.map(item=><article key={item.id} className="rounded-xl border border-border bg-secondary/20 p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0"><h3 className="break-words font-bold">{item.titulo}</h3><div className="mt-2 flex flex-wrap items-center gap-2"><span className="text-xs text-muted-foreground">{item.horario_inicio}–{item.horario_fim}</span><AgendaStatusBadge value={item.status_agenda}/></div></div><div className="flex gap-2"><button onClick={()=>onEdit(item)} className={`${buttonSoft} h-8 w-20 px-3 text-xs`}>Editar</button><button onClick={()=>onDelete(item)} className={buttonDanger}>Excluir</button></div></div><div className="mt-3 grid grid-cols-1 gap-3 border-t border-border pt-3 text-sm sm:grid-cols-2"><Info label="Carteira" value={item.produto_carteira}/><Info label="Tipo" value={item.tipo_treinamento}/></div><ParticipantsInfo value={item.participantes}/>{item.observacoes&&<p className="mt-2 border-t border-border pt-2 text-xs text-muted-foreground">{item.observacoes}</p>}</article>):<div className="grid min-h-40 place-items-center rounded-xl border border-dashed border-border text-center"><div><p className="font-semibold">Nenhuma reunião neste dia.</p><button onClick={onNew} className={`${buttonSoft} mt-3`}>+ Criar reunião</button></div></div>}</div></section></div>}

function TrainingAgenda(){
 const [month,setMonth]=useState(startOfMonth(new Date())); const [items,setItems]=useState<AgendaItem[]>([]); const [loading,setLoading]=useState(true); const [modal,setModal]=useState(false); const [selected,setSelected]=useState(today);
 const gridStart=startOfWeek(startOfMonth(month),{weekStartsOn:0}); const gridEnd=endOfWeek(endOfMonth(month),{weekStartsOn:0});
 const days=useMemo(()=>{const list:Date[]=[];for(let cursor=gridStart;cursor<=gridEnd;cursor=new Date(cursor.getFullYear(),cursor.getMonth(),cursor.getDate()+1))list.push(cursor);return list},[gridStart.getTime(),gridEnd.getTime()]);
 const load=useCallback(async()=>{setLoading(true);try{const p=new URLSearchParams({inicio:format(gridStart,"yyyy-MM-dd"),fim:format(gridEnd,"yyyy-MM-dd")});setItems((await listarAgendaTreinamentos(p)).itens)}finally{setLoading(false)}},[gridStart.getTime(),gridEnd.getTime()]);
 useEffect(()=>{void load()},[load]);
 return <div className="min-h-full bg-background p-4 text-foreground sm:p-6 lg:p-8"><div className="mx-auto max-w-[1500px] space-y-6">
  <header className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">Qualidade</p><h1 className="mt-1 text-3xl font-bold">Treinamentos</h1><p className="mt-1 text-sm text-muted-foreground">Planejamento mensal das capacitações, sem notificações por e-mail.</p></div><button onClick={()=>setModal(true)} className={`${buttonPrimary} h-11 px-5`}>+ Agendar treinamento</button></header>
  <section className="overflow-hidden rounded-2xl border border-border bg-card shadow-xl"><div className="flex items-center justify-between border-b border-border p-4"><button onClick={()=>setMonth(addMonths(month,-1))} className="grid size-9 appearance-none place-items-center rounded-lg border border-border bg-secondary/50 text-foreground transition hover:border-primary/50 hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40">‹</button><div className="text-center"><p className="text-xs font-bold uppercase tracking-widest text-primary">Agenda mensal</p><h2 className="text-xl font-bold capitalize">{format(month,"MMMM 'de' yyyy",{locale:ptBR})}</h2></div><button onClick={()=>setMonth(addMonths(month,1))} className="grid size-9 appearance-none place-items-center rounded-lg border border-border bg-secondary/50 text-foreground transition hover:border-primary/50 hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40">›</button></div>
   <div className="grid grid-cols-7 border-b border-border bg-secondary/30">{["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map(d=><div key={d} className="p-3 text-center text-[11px] font-bold uppercase tracking-wider text-muted-foreground">{d}</div>)}</div>
   <div className="grid grid-cols-7">{days.map(day=>{const key=format(day,"yyyy-MM-dd");const dayItems=items.filter(i=>i.data_treinamento===key);return <div key={key} role="button" tabIndex={0} onClick={()=>{setSelected(key);setModal(true)}} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){setSelected(key);setModal(true)}}} className={`min-h-32 cursor-pointer border-b border-r border-border p-2 text-left align-top transition hover:bg-primary/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary/40 ${isSameMonth(day,month)?"bg-card":"bg-background/40 text-muted-foreground/40"}`}><span className={`grid size-7 place-items-center rounded-full text-xs font-bold ${key===today?"bg-primary text-primary-foreground":""}`}>{format(day,"d")}</span><div className="mt-2 space-y-1">{dayItems.slice(0,3).map(item=><div key={item.id} onClick={e=>e.stopPropagation()} className="group rounded-md border border-primary/25 bg-primary/10 px-2 py-1.5 text-[11px]"><div className="flex items-center gap-1"><span className="size-1.5 rounded-full bg-primary"/><strong className="truncate text-foreground">{item.horario_inicio} · {item.titulo}</strong></div><p className="truncate text-muted-foreground">{item.produto_carteira} · {item.responsavel}</p><button onClick={async()=>{if(confirm("Excluir este agendamento?")){await excluirAgendaTreinamento(item.id);void load()}}} className={`${buttonDanger} mt-1 hidden h-7 group-hover:inline-flex`}>Excluir</button></div>)}{dayItems.length>3&&<p className="text-[10px] font-bold text-primary">+ {dayItems.length-3} eventos</p>}</div></div>})}</div>
  </section>{loading&&<p className="text-center text-sm text-muted-foreground">Atualizando agenda…</p>}
 </div>{modal&&<AgendaModal date={selected} onClose={()=>setModal(false)} onSaved={()=>{setModal(false);void load()}}/>}</div>
}

const splitMulti=(value?:string)=>Array.from(new Set((value||"").split(/[;,\n]+/).map(x=>x.trim()).filter(Boolean)));
function MultiCarteiraSelect({defaultValue=""}:{defaultValue?:string}){const [values,setValues]=useState(()=>splitMulti(defaultValue));function add(value:string){if(value&&!values.includes(value))setValues(current=>[...current,value])}return <div className="md:col-span-2"><input type="hidden" name="produto_carteira" value={values.join("; ")}/><CarteiraSelect key={values.length} label="Carteiras da reunião" value="" onChange={add}/><div className="mt-2 flex flex-wrap gap-2">{values.map(value=><button type="button" key={value} onClick={()=>setValues(current=>current.filter(x=>x!==value))} className="rounded-lg border border-primary/30 bg-primary/10 px-2.5 py-1 text-xs font-bold text-primary">{value} ×</button>)}</div>{!values.length&&<p className="mt-1 text-[10px] text-amber-300">Adicione pelo menos uma carteira.</p>}</div>}
function MultiResponsavelSelect({defaultValue=""}:{defaultValue?:string}){const [values,setValues]=useState(()=>splitMulti(defaultValue));function add(value:string){if(value&&!values.includes(value))setValues(current=>[...current,value])}return <div className="md:col-span-2"><input type="hidden" name="responsavel" value={values.join("; ")}/><ResponsavelQualidadeSelect key={values.length} value="" onChange={add} required={false}/><div className="mt-2 flex flex-wrap gap-2">{values.map(value=><button type="button" key={value} onClick={()=>setValues(current=>current.filter(x=>x!==value))} className="rounded-lg border border-primary/30 bg-primary/10 px-2.5 py-1 text-xs font-bold text-primary">{value} ×</button>)}</div>{!values.length&&<p className="mt-1 text-[10px] text-amber-300">Adicione pelo menos um responsável.</p>}</div>}

function AgendaModal({date,onClose,onSaved,item}:{date:string;onClose:()=>void;onSaved:()=>void;item?:AgendaItem}){
 const [saving,setSaving]=useState(false);const [error,setError]=useState("");const [diaEncontro,setDiaEncontro]=useState<1|2>(item?.dia_encontro||1);const [criarDia2,setCriarDia2]=useState(false);const [ciclos,setCiclos]=useState<AgendaOption[]>([]);const [agendaVinculadaId,setAgendaVinculadaId]=useState("");const [operadores,setOperadores]=useState<{colaborador:string;cpf:string}[]>([]);const [operadoresExistentes,setOperadoresExistentes]=useState<Admissao[]>([]);const [removidos,setRemovidos]=useState<number[]>([]);
 useEffect(()=>{void listarOpcoesAgendaTreinamentos().then(result=>setCiclos((result.itens||[]).filter((agenda:AgendaOption)=>!agenda.possui_dia_2))).catch(()=>setCiclos([]))},[]);
 useEffect(()=>{if(!item){setOperadoresExistentes([]);return}const params=new URLSearchParams({agenda_id:String(item.id)});void listarAdmissoesTreinamento(params).then(result=>setOperadoresExistentes(result.itens||[])).catch(()=>setOperadoresExistentes([]))},[item?.id]);
 const agendaDia1=diaEncontro===2?ciclos.find(agenda=>String(agenda.id)===agendaVinculadaId):undefined;
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);setError("");try{const payload=Object.fromEntries(new FormData(e.currentTarget).entries());if(!payload.produto_carteira||!payload.responsavel)throw new Error("Adicione ao menos uma carteira e um responsável.");let agendaId:number|undefined;if(item){await atualizarAgendaTreinamento(item.id,payload);agendaId=item.id}else{const result=await criarAgendaTreinamento(payload);agendaId=result?.id}const novosOperadores=operadores.map(o=>({colaborador:o.colaborador.trim(),cpf:o.cpf.trim()})).filter(o=>o.colaborador.length>=2&&o.cpf.replace(/\D/g,"").length===11);if(agendaId&&novosOperadores.length)await criarAdmissoesLote(novosOperadores.map(o=>({agenda_id:String(agendaId),colaborador:o.colaborador,cpf:o.cpf,status_primeiro_dia:"PREVISTO",status_segundo_dia:"PREVISTO"})));for(const id of removidos)await excluirAdmissao(id);onSaved()}catch(err){setError(getApiError(err,`Não foi possível ${item?"atualizar":"criar"} o agendamento. Adicione ao menos uma carteira e um responsável.`))}finally{setSaving(false)}}
 return <div className="fixed inset-0 z-[60] grid place-items-center bg-black/75 p-4"><form onSubmit={submit} className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-3xl border border-border bg-card p-6 shadow-2xl"><div className="mb-6 flex justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-primary">Agenda de treinamentos</p><h2 className="text-2xl font-bold">{item?"Editar agendamento":"Novo agendamento"}</h2></div><button type="button" onClick={onClose} className="grid size-9 appearance-none place-items-center rounded-lg border border-border bg-secondary/50 text-xl text-muted-foreground transition hover:border-primary/50 hover:bg-muted hover:text-foreground">×</button></div>{error&&<p className="mb-4 rounded-xl bg-red-500/10 p-3 text-sm text-red-300">{error}</p>}<div className="grid gap-4 md:grid-cols-2"><Field label="Título"><input required name="titulo" key={`titulo-${agendaDia1?.id||0}`} defaultValue={agendaDia1?.titulo||item?.titulo||""} className={inputClass} placeholder="Treinamento inicial Vega"/></Field><Field label="Data"><input required name="data_treinamento" type="date" defaultValue={item?.data_treinamento||date} className={inputClass}/></Field><Field label="Início"><input required name="horario_inicio" type="time" defaultValue={item?.horario_inicio||"09:00"} className={inputClass}/></Field><Field label="Fim"><input required name="horario_fim" type="time" defaultValue={item?.horario_fim||"12:00"} className={inputClass}/></Field><Field label="Tipo"><select name="tipo_treinamento" key={`tipo-${agendaDia1?.id||0}`} defaultValue={agendaDia1?.tipo_treinamento||item?.tipo_treinamento||"INICIAL"} className={inputClass}>{["INICIAL","REMANEJAMENTO","CALIBRAGEM"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Status"><select name="status_agenda" key={`status-${agendaDia1?.id||0}`} defaultValue={agendaDia1?.status_agenda||item?.status_agenda||"AGENDADO"} className={inputClass}>{["AGENDADO","REALIZADO","CANCELADO"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Etapa do ciclo"><select name="dia_encontro" value={diaEncontro} disabled={!!item} onChange={e=>setDiaEncontro(Number(e.target.value) as 1|2)} className={inputClass}><option value={1}>Dia 1</option><option value={2}>Dia 2</option></select>{item&&<input type="hidden" name="dia_encontro" value={diaEncontro}/>}</Field>{!item&&diaEncontro===2&&<Field label="Vincular ao Dia 1 *"><select required name="agenda_vinculada_id" value={agendaVinculadaId} onChange={e=>setAgendaVinculadaId(e.target.value)} className={inputClass}><option value="">Selecione o ciclo</option>{ciclos.map(agenda=><option key={agenda.id} value={agenda.id}>{agendaLabel(agenda)}</option>)}</select></Field>}{!item&&diaEncontro===1&&<label className="flex items-center gap-2 rounded-xl border border-border bg-secondary/30 px-3 text-sm font-semibold text-foreground"><input type="checkbox" name="criar_dia_2" value="true" checked={criarDia2} onChange={e=>setCriarDia2(e.target.checked)}/> Criar também o Dia 2</label>}{!item&&diaEncontro===1&&criarDia2&&<><Field label="Data do Dia 2 *"><input required name="data_dia_2" type="date" className={inputClass}/></Field><Field label="Início do Dia 2 *"><input required name="horario_inicio_dia_2" type="time" defaultValue={item?.horario_inicio||"09:00"} className={inputClass}/></Field><Field label="Fim do Dia 2 *"><input required name="horario_fim_dia_2" type="time" defaultValue={item?.horario_fim||"12:00"} className={inputClass}/></Field></>}<MultiCarteiraSelect key={`carteiras-${agendaDia1?.id||0}`} defaultValue={agendaDia1?.produto_carteira||item?.produto_carteira||""}/><MultiResponsavelSelect key={`responsaveis-${agendaDia1?.id||0}`} defaultValue={agendaDia1?.responsavel||item?.responsavel||""}/><input type="hidden" name="participantes" value={item?.participantes||""}/><div className="md:col-span-2 rounded-xl border border-border bg-secondary/20 p-3"><div className="mb-2 flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-wide text-primary">Operadores{item?" da reunião":" (opcional)"}</p><p className="text-[10px] text-muted-foreground">{item?"Adicione novos ou remova operadores desta reunião. As remoções são aplicadas ao salvar.":"Cadastre já as admissões desta agenda. Entram como PREVISTO e podem ser ajustadas depois."}</p></div><button type="button" className={`${buttonSoft} h-9 px-3 text-xs`} onClick={()=>setOperadores(current=>[...current,{colaborador:"",cpf:""}])}>+ Adicionar operador</button></div>{item&&operadoresExistentes.length>0&&<div className="mb-2 flex flex-wrap gap-2">{operadoresExistentes.map(op=>{const marcado=removidos.includes(op.id);return <button type="button" key={op.id} onClick={()=>setRemovidos(list=>marcado?list.filter(id=>id!==op.id):[...list,op.id])} title={marcado?"Desfazer remoção":"Remover desta reunião"} className={`inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1 text-xs font-bold transition ${marcado?"border-red-400/40 bg-red-500/10 text-red-300 line-through":"border-primary/30 bg-primary/10 text-primary hover:border-primary/60 hover:bg-primary/20"}`}>{op.colaborador} {marcado?"↺":"×"}</button>})}</div>}{item&&removidos.length>0&&<p className="mb-2 text-[10px] text-amber-300">{removidos.length} operador(es) serão removidos ao salvar.</p>}{operadores.length>0&&<div className="space-y-2">{operadores.map((op,index)=><div key={index} className="flex flex-wrap items-end gap-2"><div className="min-w-0 flex-1"><Field label="Colaborador"><input value={op.colaborador} onChange={e=>setOperadores(list=>list.map((it,i)=>i===index?{...it,colaborador:e.target.value}:it))} className={`${inputClass} w-full`} placeholder="Nome do operador"/></Field></div><div className="w-full sm:w-44"><Field label="CPF"><input value={op.cpf} onChange={e=>setOperadores(list=>list.map((it,i)=>i===index?{...it,cpf:e.target.value}:it))} className={`${inputClass} w-full`} maxLength={14} placeholder="Somente números"/></Field></div><button type="button" className={buttonDanger} onClick={()=>setOperadores(list=>list.filter((_,i)=>i!==index))}>Remover</button></div>)}</div>}{!operadores.length&&!(item&&operadoresExistentes.length)&&<p className="text-[10px] text-muted-foreground">Nenhum operador {item?"vinculado":"adicionado"}. Opcional — você também pode incluir depois em Admissões.</p>}</div><label className="grid gap-1 text-xs font-semibold text-muted-foreground md:col-span-2">Observações<textarea name="observacoes" key={`observacoes-${agendaDia1?.id||0}`} defaultValue={agendaDia1?.observacoes||item?.observacoes||""} className="min-h-20 rounded-xl border border-border bg-input p-3 text-sm text-foreground"/></label></div><div className="mt-6 flex justify-end gap-3"><button type="button" onClick={onClose} className={buttonSecondary}>Cancelar</button><button disabled={saving} className={`${buttonPrimary} px-5`}>{saving?"Salvando…":item?"Salvar alterações":"Criar agendamento"}</button></div></form></div>
}

// ============================ Monitorias VEGA ============================
type VegaSemana={semana:number;total:number;conforme:number;inconforme:number;pct_conforme:number;pct_inconforme:number};
type VegaMes={mes:number;mes_nome:string;mes_abrev:string;total:number;conforme:number;inconforme:number;pct_conforme:number;pct_inconforme:number};
type VegaResumo={total:number;conforme:number;inconforme:number;pct_conforme:number;pct_inconforme:number};
type VegaDashboardData={ano:number;mes:number;mes_nome:string;kpis:VegaResumo;semanas:VegaSemana[];meses:VegaMes[];resumo_semanal:VegaSemana[];consolidado_ano:VegaResumo};
const MESES_VEGA=["","Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
const fmtInt=(n:number)=>Math.round(n||0).toLocaleString("pt-BR");
const fmtPct=(n:number)=>(n||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})+"%";

function VegaKpi({title,value,detail,color}:{title:string;value:string;detail:string;color:string}){const colors:Record<string,string>={green:"bg-emerald-500/10 text-emerald-300",red:"bg-red-500/10 text-red-300",blue:"bg-sky-500/10 text-sky-300",slate:"bg-primary/10 text-primary"};return <div className="rounded-2xl border border-border bg-card p-5 shadow-sm"><div className={`mb-4 grid size-9 place-items-center rounded-xl ${colors[color]||colors.slate}`}>●</div><p className="text-sm font-semibold text-muted-foreground">{title}</p><p className="mt-1 text-3xl font-bold text-foreground">{value}</p><p className="mt-2 text-xs text-muted-foreground">{detail}</p></div>}

function MonitoriasVegaDashboard(){
  const now=new Date();
  const [ano,setAno]=useState(now.getFullYear());
  const [mes,setMes]=useState(now.getMonth()+1);
  const [anos,setAnos]=useState<number[]>([now.getFullYear()]);
  const [data,setData]=useState<VegaDashboardData|null>(null);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState("");
  const [modalOpen,setModalOpen]=useState(false);
  const [exportando,setExportando]=useState(false);
  const carregar=useCallback(async()=>{setLoading(true);setError("");try{setData(await listarDashboardMonitoriasVega(ano,mes))}catch{setError("Não foi possível carregar as monitorias da Vega. Tente novamente.")}finally{setLoading(false)}},[ano,mes]);
  async function exportar(){setExportando(true);setError("");try{const blob=await exportarMonitoriasVega(ano);const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=`monitorias-vega-${ano}.xlsx`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch{setError("Não foi possível exportar o Excel. Tente novamente.")}finally{setExportando(false)}}
  useEffect(()=>{void carregar()},[carregar]);
  useEffect(()=>{void listarAnosMonitoriasVega().then(result=>{const itens:number[]=result.itens?.length?result.itens:[now.getFullYear()];setAnos(itens);setAno(current=>itens.includes(current)?current:itens[0])}).catch(()=>{})},[]);
  const k=data?.kpis; const maxMes=Math.max(1,...(data?.meses||[]).map(item=>item.total));
  return <div className="space-y-6">
    <section className="flex flex-wrap items-end gap-3 rounded-2xl border border-border bg-card p-4 shadow-sm">
      <Field label="Ano"><select className={`${inputClass} w-full sm:w-32`} value={ano} onChange={e=>setAno(Number(e.target.value))}>{anos.map(item=><option key={item} value={item}>{item}</option>)}</select></Field>
      <Field label="Mês"><select className={`${inputClass} w-full sm:w-44`} value={mes} onChange={e=>setMes(Number(e.target.value))}>{MESES_VEGA.slice(1).map((nome,index)=><option key={index+1} value={index+1}>{nome}</option>)}</select></Field>
      <button onClick={()=>void carregar()} className={buttonPrimary}>Atualizar</button>
      <div className="ml-auto flex flex-wrap gap-2">
        <button onClick={()=>void exportar()} disabled={exportando||loading} className={buttonSecondary}>{exportando?"Gerando Excel…":"Exportar Excel"}</button>
        <button onClick={()=>setModalOpen(true)} className={buttonSoft}>Lançar / importar dados</button>
      </div>
    </section>
    {error&&<div className="rounded-xl border border-red-400/30 bg-red-500/10 p-4 text-sm text-red-300">{error}</div>}
    {loading?<div className="grid h-56 place-items-center text-sm text-muted-foreground">Carregando informações…</div>:<>
      <div className="flex flex-wrap items-baseline justify-between gap-2"><h2 className="text-lg font-bold">{data?.mes_nome} · {ano}</h2><span className="text-xs text-muted-foreground">Consolidado do mês selecionado</span></div>
      <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-5">
        <VegaKpi title="Total de monitorias" value={fmtInt(k?.total||0)} detail="Realizadas no mês" color="slate"/>
        <VegaKpi title="Conformes" value={fmtInt(k?.conforme||0)} detail="Sem desvios / aprovadas" color="green"/>
        <VegaKpi title="Inconformes" value={fmtInt(k?.inconforme||0)} detail="Com desvios / reprovadas" color="red"/>
        <VegaKpi title="% Conformidade" value={fmtPct(k?.pct_conforme||0)} detail="Conformes / Total" color="green"/>
        <VegaKpi title="% Inconformidade" value={fmtPct(k?.pct_inconforme||0)} detail="Inconformes / Total" color="red"/>
      </section>
      <DataCard title="Detalhamento por semana"><table><thead><tr><th>Semana</th><th className="text-right">Total</th><th className="text-right">Conformes</th><th className="text-right">Inconformes</th><th className="text-right">% Conformidade</th><th className="text-right">% Inconformidade</th></tr></thead><tbody>
        {(data?.semanas||[]).map(item=><tr key={item.semana}><td className="font-semibold">Semana {String(item.semana).padStart(2,"0")}</td><td className="text-right">{fmtInt(item.total)}</td><td className="text-right text-emerald-300">{fmtInt(item.conforme)}</td><td className="text-right text-red-300">{fmtInt(item.inconforme)}</td><td className="text-right font-bold">{item.total?fmtPct(item.pct_conforme):"—"}</td><td className="text-right">{item.total?fmtPct(item.pct_inconforme):"—"}</td></tr>)}
        <tr className="font-bold [&>td]:bg-secondary/30"><td>Total do mês</td><td className="text-right">{fmtInt(k?.total||0)}</td><td className="text-right text-emerald-300">{fmtInt(k?.conforme||0)}</td><td className="text-right text-red-300">{fmtInt(k?.inconforme||0)}</td><td className="text-right">{fmtPct(k?.pct_conforme||0)}</td><td className="text-right">{fmtPct(k?.pct_inconforme||0)}</td></tr>
      </tbody></table></DataCard>
      <DataCard title={`Total por semana · ${ano}`}><table><thead><tr><th>Semana</th><th className="text-right">Total</th><th className="text-right">Conformes</th><th className="text-right">Inconformes</th><th className="text-right">% Conformidade</th><th className="text-right">% Inconformidade</th></tr></thead><tbody>
        {(data?.resumo_semanal||[]).map(item=><tr key={item.semana}><td className="whitespace-nowrap font-semibold">Semana {String(item.semana).padStart(2,"0")}</td><td className="text-right">{item.total?fmtInt(item.total):"—"}</td><td className="text-right text-emerald-300">{item.total?fmtInt(item.conforme):"—"}</td><td className="text-right text-red-300">{item.total?fmtInt(item.inconforme):"—"}</td><td className="text-right font-bold">{item.total?fmtPct(item.pct_conforme):"—"}</td><td className="text-right">{item.total?fmtPct(item.pct_inconforme):"—"}</td></tr>)}
        <tr className="font-bold [&>td]:bg-secondary/40"><td className="whitespace-nowrap">Total do ano</td><td className="text-right">{fmtInt(data?.consolidado_ano.total||0)}</td><td className="text-right text-emerald-300">{fmtInt(data?.consolidado_ano.conforme||0)}</td><td className="text-right text-red-300">{fmtInt(data?.consolidado_ano.inconforme||0)}</td><td className="text-right">{fmtPct(data?.consolidado_ano.pct_conforme||0)}</td><td className="text-right">{fmtPct(data?.consolidado_ano.pct_inconforme||0)}</td></tr>
      </tbody></table></DataCard>
      <section className="rounded-2xl border border-border bg-card p-5 shadow-sm">
        <div className="mb-4 flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">Conformes vs Inconformes · {ano}</h3><div className="flex gap-3 text-xs text-muted-foreground"><span className="flex items-center gap-1"><span className="size-2 rounded-full bg-emerald-400"/>Conformes</span><span className="flex items-center gap-1"><span className="size-2 rounded-full bg-red-400"/>Inconformes</span></div></div>
        <div className="flex items-end gap-1.5 overflow-x-auto pb-1 sm:gap-3">
          {(data?.meses||[]).map(item=>{const barH=maxMes?Math.round(item.total/maxMes*160):0;const confH=item.total?Math.round(item.conforme/item.total*barH):0;const incH=Math.max(0,barH-confH);const atual=item.mes===mes;return <div key={item.mes} className="flex min-w-[26px] flex-1 flex-col items-center gap-1">
            <span className="text-[10px] font-semibold text-muted-foreground">{item.total?fmtInt(item.total):""}</span>
            <div className="flex w-full flex-col justify-end" style={{height:160}} title={`${item.mes_nome}: ${fmtInt(item.total)} total · ${fmtInt(item.conforme)} conformes · ${fmtInt(item.inconforme)} inconformes`}>
              <div className="w-full rounded-t bg-red-400/80" style={{height:incH}}/>
              <div className={`w-full rounded-b bg-emerald-400/80 ${incH?"":"rounded-t"}`} style={{height:confH}}/>
            </div>
            <span className={`text-[10px] ${atual?"font-bold text-primary":"text-muted-foreground"}`}>{item.mes_abrev}</span>
          </div>})}
        </div>
      </section>
      <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <VegaKpi title="Total no ano" value={fmtInt(data?.consolidado_ano.total||0)} detail={`Acumulado de ${ano}`} color="slate"/>
        <VegaKpi title="Conformes no ano" value={fmtInt(data?.consolidado_ano.conforme||0)} detail={fmtPct(data?.consolidado_ano.pct_conforme||0)} color="green"/>
        <VegaKpi title="Inconformes no ano" value={fmtInt(data?.consolidado_ano.inconforme||0)} detail={fmtPct(data?.consolidado_ano.pct_inconforme||0)} color="red"/>
        <VegaKpi title="% Conformidade no ano" value={fmtPct(data?.consolidado_ano.pct_conforme||0)} detail="Conformes / Total do ano" color="green"/>
      </section>
    </>}
    {modalOpen&&<MonitoriasVegaModal ano={ano} mes={mes} anos={anos} weeks={data?.semanas||[]} onClose={()=>setModalOpen(false)} onSaved={()=>{setModalOpen(false);void carregar()}}/>}
  </div>;
}

type VegaWeekRow={semana:number;total:number|"";conforme:number|"";inconforme:number|""};
type VegaParsed={dados:{ano:number;mes:number;mes_nome?:string;semana:number;total:number;conforme:number;inconforme:number};erros:string[];valido:boolean};
function MonitoriasVegaModal({ano,mes,anos,weeks,onClose,onSaved}:{ano:number;mes:number;anos:number[];weeks:VegaSemana[];onClose:()=>void;onSaved:()=>void}){
  const [mode,setMode]=useState<"manual"|"excel">("manual");
  const [editAno,setEditAno]=useState(ano);
  const [editMes,setEditMes]=useState(mes);
  const [rows,setRows]=useState<VegaWeekRow[]>(()=>[1,2,3,4,5].map(semana=>{const w=weeks.find(item=>item.semana===semana);return {semana,total:w?.total||0,conforme:w?.conforme||0,inconforme:w?.inconforme||0}}));
  const [parsed,setParsed]=useState<VegaParsed[]>([]);
  const [fileName,setFileName]=useState("");
  const [loading,setLoading]=useState(false);
  const [loadingMes,setLoadingMes]=useState(false);
  const [error,setError]=useState("");
  const primeiraCarga=useMemo(()=>({ano,mes}),[ano,mes]);
  useEffect(()=>{if(editAno===primeiraCarga.ano&&editMes===primeiraCarga.mes)return;let ativo=true;setLoadingMes(true);void listarDashboardMonitoriasVega(editAno,editMes).then((d:VegaDashboardData)=>{if(!ativo)return;const semanas=d.semanas||[];setRows([1,2,3,4,5].map(semana=>{const w=semanas.find(item=>item.semana===semana);return {semana,total:w?.total||0,conforme:w?.conforme||0,inconforme:w?.inconforme||0}}))}).catch(()=>{if(ativo)setError("Não foi possível carregar o mês selecionado.")}).finally(()=>{if(ativo)setLoadingMes(false)});return()=>{ativo=false}},[editAno,editMes,primeiraCarga]);
  const anosOpcoes=anos.includes(editAno)?anos:[...anos,editAno].sort((a,b)=>b-a);
  function change(index:number,key:"total"|"conforme"|"inconforme",value:string){const limpo=value.replace(/\D/g,"");setRows(current=>current.map((row,i)=>i===index?{...row,[key]:limpo===""?"":Number(limpo)}:row))}
  async function analyze(file?:File){if(!file)return;setLoading(true);setError("");try{const result=await analisarPlanilhaMonitoriasVega(file);setFileName(`${result.arquivo} · ${result.aba}`);setParsed(result.itens||[])}catch{setError("Não foi possível analisar a planilha. Confira se é o arquivo 'Dashboard - Monitorias' com a aba 'Controle das Monitorias'.")}finally{setLoading(false)}}
  async function save(){setLoading(true);setError("");try{
    const payload=mode==="manual"
      ? rows.filter(row=>Number(row.total)||Number(row.conforme)||Number(row.inconforme)).map(row=>({ano:editAno,mes:editMes,semana:row.semana,total:Number(row.total)||0,conforme:Number(row.conforme)||0,inconforme:Number(row.inconforme)||0}))
      : parsed.filter(item=>item.valido).map(item=>({ano:item.dados.ano,mes:item.dados.mes,semana:item.dados.semana,total:item.dados.total,conforme:item.dados.conforme,inconforme:item.dados.inconforme}));
    if(!payload.length){setError(mode==="manual"?"Preencha ao menos uma semana com valores.":"Nenhum registro válido para importar.");setLoading(false);return}
    await salvarMonitoriasVegaLote(payload);onSaved();
  }catch(err){setError(getApiError(err,"Não foi possível gravar os dados. Revise os valores e tente novamente."))}finally{setLoading(false)}}
  return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-3"><section className="flex max-h-[94vh] w-full max-w-[900px] flex-col overflow-hidden rounded-3xl border border-border bg-card shadow-2xl">
    <header className="flex items-start justify-between border-b border-border p-5"><div><p className="text-xs font-bold uppercase tracking-widest text-primary">Monitorias VEGA</p><h2 className="text-2xl font-bold">Lançar dados de monitorias</h2><p className="text-sm text-muted-foreground">{mode==="manual"?"Escolha o mês, edite as semanas e grave. Os valores substituem os já existentes.":"Importe a planilha para carregar todos os meses e semanas de uma vez."}</p></div><button onClick={onClose} className="grid size-9 appearance-none place-items-center rounded-lg border border-border bg-secondary/50 text-xl text-muted-foreground hover:border-primary/50 hover:text-foreground">×</button></header>
    <div className="flex flex-wrap items-center gap-3 border-b border-border p-4"><div className="flex rounded-xl border border-border bg-secondary/30 p-1"><button onClick={()=>setMode("manual")} className={`h-9 appearance-none rounded-lg border px-4 text-sm font-bold transition ${mode==="manual"?"border-primary bg-primary text-primary-foreground":"border-transparent bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground"}`}>Lançar manualmente</button><button onClick={()=>setMode("excel")} className={`h-9 appearance-none rounded-lg border px-4 text-sm font-bold transition ${mode==="excel"?"border-primary bg-primary text-primary-foreground":"border-transparent bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground"}`}>Importar planilha</button></div>{mode==="excel"&&<label className={`${buttonSoft} cursor-pointer`}>Selecionar .xlsx ou .xlsm<input type="file" accept=".xlsx,.xlsm" className="hidden" onChange={e=>void analyze(e.target.files?.[0])}/></label>}{fileName&&<span className="text-xs text-muted-foreground">{fileName}</span>}<span className="ml-auto text-sm font-semibold text-muted-foreground">{mode==="manual"?`${MESES_VEGA[editMes]} · ${editAno}`:`${parsed.length} registro(s)`}</span></div>
    {mode==="manual"&&<div className="flex flex-wrap items-end gap-3 border-b border-border p-4"><Field label="Ano"><select className={`${inputClass} w-full sm:w-32`} value={editAno} onChange={e=>setEditAno(Number(e.target.value))}>{anosOpcoes.map(item=><option key={item} value={item}>{item}</option>)}</select></Field><Field label="Mês"><select className={`${inputClass} w-full sm:w-44`} value={editMes} onChange={e=>setEditMes(Number(e.target.value))}>{MESES_VEGA.slice(1).map((nome,index)=><option key={index+1} value={index+1}>{nome}</option>)}</select></Field>{loadingMes&&<span className="pb-2 text-xs text-muted-foreground">Carregando mês…</span>}</div>}
    {error&&<p className="m-4 rounded-xl border border-red-400/30 bg-red-500/10 p-3 text-sm text-red-300">{error}</p>}
    <div className="min-h-0 flex-1 space-y-3 overflow-y-auto p-4">
      {mode==="manual"?rows.map((row,index)=><article key={row.semana} className="rounded-xl border border-border bg-secondary/20 p-3"><div className="mb-3 text-xs font-bold text-primary">Semana {String(row.semana).padStart(2,"0")}</div><div className="grid gap-3 sm:grid-cols-3"><Field label="Total"><input inputMode="numeric" value={row.total} onChange={e=>change(index,"total",e.target.value)} className={`${inputClass} w-full`} placeholder="0"/></Field><Field label="Conformes"><input inputMode="numeric" value={row.conforme} onChange={e=>change(index,"conforme",e.target.value)} className={`${inputClass} w-full`} placeholder="0"/></Field><Field label="Inconformes"><input inputMode="numeric" value={row.inconforme} onChange={e=>change(index,"inconforme",e.target.value)} className={`${inputClass} w-full`} placeholder="0"/></Field></div></article>)
      :parsed.length?<div className="overflow-x-auto rounded-xl border border-border"><table className="w-full text-sm [&_td]:border-t [&_td]:border-border [&_td]:px-3 [&_td]:py-2 [&_th]:bg-secondary/50 [&_th]:px-3 [&_th]:py-2 [&_th]:text-left [&_th]:text-[11px] [&_th]:font-bold [&_th]:uppercase [&_th]:tracking-wide [&_th]:text-muted-foreground"><thead><tr><th>Ano</th><th>Mês</th><th>Semana</th><th className="text-right">Total</th><th className="text-right">Conformes</th><th className="text-right">Inconformes</th></tr></thead><tbody>{parsed.map((item,index)=><tr key={index} className={item.valido?"":"bg-red-500/5"}><td>{item.dados.ano}</td><td>{item.dados.mes_nome||item.dados.mes}</td><td>{String(item.dados.semana).padStart(2,"0")}</td><td className="text-right">{fmtInt(item.dados.total)}</td><td className="text-right text-emerald-300">{fmtInt(item.dados.conforme)}</td><td className="text-right text-red-300">{fmtInt(item.dados.inconforme)}</td></tr>)}</tbody></table></div>
      :<p className="grid h-40 place-items-center text-center text-sm text-muted-foreground">Selecione a planilha para pré-visualizar os registros.</p>}
    </div>
    <footer className="flex items-center justify-between gap-3 border-t border-border p-4"><p className="text-xs text-muted-foreground">{mode==="excel"&&parsed.length?`${parsed.filter(item=>item.valido).length} válido(s) · ${parsed.filter(item=>!item.valido).length} com erro`:"Os dados são gravados por ano, mês e semana."}</p><div className="flex gap-3"><button onClick={onClose} className={buttonSecondary}>Cancelar</button><button disabled={loading} onClick={()=>void save()} className={`${buttonPrimary} px-5`}>{loading?"Gravando…":"Gravar dados"}</button></div></footer>
  </section></div>;
}
